    ["05-d1"] = {name="El Salón de los Feudales", entrance="Forjaz 27.63, 47.83", pickup="Acepta las misiones de la mazmorra al pasar por Dun Morogh y Loch Modan; así no tendrás que volver antes de entrar.", pickupS={{"Acepta las misiones de la mazmorra al pasar por Dun Morogh y Loch Modan; así no tendrás que volver antes de entrar"}}, steps={[1]={npc="Mapa Hierro Negro", npcObj=true, tag="Requisito de mazmorra"}, [2]={npc="Videnterra Farsen", tgt="Videnterra Farsen", tag="Requisito de mazmorra"}, [3]={npc="Videnterra Farsen", tgt="Videnterra Farsen"}, [4]={npc="Afadra Murocre", tgt="Afadra Murocre"}, [5]={npc="Thom Filch", tgt="Thom Filch"}, [6]={npc="Ghostly Attendant", tgt="Ghostly Attendant"}, [7]={text="Entrada: El Salón de los Feudales"}, [8]={npc="Ghostly Attendant", tgt="Ghostly Attendant"}, [9]={hint="Mata a 15 apariciones iracundas y 10 almas atormentadas, antes de acabar con el espíritu de Yunquemar."}, [10]={hint="Recupera 8 reliquias enanas en el Salón de los Feudales."}, [11]={hint="Entra en el Salón de los Feudales bajo Antigua Forjaz y hazte con la cabeza de Durgen Martillo Funesto."}, [12]={npc="Treaty of Understanding", npcObj=true, desc="Haz clic derecho en Tratado de entendimiento en tu bolsa para empezar la misión. El jefe final lanza Miedo hacia el 35 % de salud. Limpia primero los esbirros y luego lleva al jefe a la sala anterior. Junto a quien da la misión hay una palanca. Tira de ella para abrir la puerta y sal en línea recta."}, [13]={npc="Thom Filch", tgt="Thom Filch"}, [14]={npc="Afadra Murocre", tgt="Afadra Murocre"}, [15]={npc="Rey Magni Barbabronce", tgt="Rey Magni Barbabronce"}, [16]={npc="Rey Magni Barbabronce", tgt="Rey Magni Barbabronce"}}},
